pub trait Graph { type EdgeType ; fn adjacent_edges (& self , node_id : u32) -> Box < dyn Iterator < Item = & Self :: EdgeType > > ; } # [derive (Default)] pub struct Edge < T > { pub from : u32 , pub to : u32 , pub val : T , } pub struct AdjacentListGraph < T > { adjacent_lists : Vec < Vec < Edge < T > > > } impl < T > Graph for AdjacentListGraph < T > { type EdgeType = Edge < T > ; fn adjacent_edges (& self , node_id : u32) -> Box < dyn Iterator < Item = & Self :: EdgeType > + '_ > { if self . not_valid_node_id (node_id) { panic ! ("Node does not exist in the graph") ; } unsafe { Box :: new (self . adjacent_lists . get_unchecked (node_id as usize) . iter ()) } } } impl < T > AdjacentListGraph < T > { pub fn new (num_nodes : u32) -> AdjacentListGraph < T > { AdjacentListGraph { adjacent_lists : { let mut temp = Vec :: with_capacity (num_nodes as usize) ; for i in 0 .. num_nodes { temp . push (Vec :: new ()) ; } temp } } } fn not_valid_node_id (& self , node_id : u32) -> bool { return node_id >= self . num_nodes () ; } } # [cfg (test)] mod tests { use crate :: graph :: { AdjacentListGraph , Graph , Edge } ; # [test] fn test_adjacent_list_graph () { const NUM_NODES : u32 = 128 ; let mut graph = AdjacentListGraph :: new (NUM_NODES) ; assert_eq ! (NUM_NODES , graph . num_nodes ()) ; assert_eq ! (0 , graph . num_edges ()) ; graph . add_edge (Edge { from : 0 , to : 12 , val : 45 }) ; assert_eq ! (1 , graph . num_edges ()) ; let var = graph . adjacent_edges (0) ; assert_eq ! (1 , var . count ()) ; graph . add_edge (Edge { from : 2 , to : 55 , val : 546 }) ; assert_eq ! (2 , graph . num_edges ()) ; } }